def dihedrals(a):
 return {'id':a,'r90':np.rot90(a),'r180':np.rot90(a,2),'r270':np.rot90(a,3),'flipud':np.flipud(a),'fliplr':np.fliplr(a),'transpose':a.T,'anti':np.fliplr(np.flipud(a.T))}
for i,text in enumerate(usr[1:3],1):
 mi=re.search(r'Demo pair \d+ input \((\d+)x\d+\):\n(.*?)\nDemo pair \d+ output',text,re.S);mo=re.search(r'Demo pair \d+ output \((\d+)x\d+\):\n(.*?)(?:\n\nSame instance)',text,re.S)
 n=int(mi.group(1)); inp=np.array([[int(x) for x in row.split()] for row in mi.group(2).splitlines()]); out=np.array([[int(x) for x in row.split()] for row in mo.group(2).splitlines()])
 print('demo',i)
 for a in range(2):
  for b in range(2):
   q=out[a*n:(a+1)*n,b*n:(b+1)*n]
   print((a,b),[name for name,t in dihedrals(inp).items() if np.array_equal(q,t)])
